package prefrontal

import "testing"
func TestCortexRuntime(t *testing.T){c,err:=New(0.1,4);if err!=nil{t.Fatal(err)};in:=[]Candidate{{ID:"a",Utility:.8,Cost:.1,Risk:.1},{ID:"b",Utility:.7,Cost:.05,Risk:.05}};if _,err=c.Evaluate(in);err!=nil{t.Fatal(err)};if _,err=c.Plan(in);err!=nil{t.Fatal(err)};if _,err=c.Prioritize(in);err!=nil{t.Fatal(err)};if c.Inhibit(Candidate{ID:"x",Utility:.1,Risk:.9})!=true{t.Fatal("risk policy failed")};v,err:=c.Select(in);if err!=nil{t.Fatal(err)};if err=c.ValidateAction(v);err!=nil{t.Fatal(err)};if _,err=c.Commit(v,"test");err!=nil{t.Fatal(err)};if len(c.Recall(1))!=1{t.Fatal("recall failed")};if c.Health()["status"]!="ready"{t.Fatal("cortex unhealthy")}}
func TestPrioritizeDoesNotDoubleCountPriorityFactors(t *testing.T){c,err:=New(.1,4);if err!=nil{t.Fatal(err)};c.policy.UrgencyWeight=.5;c.policy.ImpactWeight=.25;candidate:=Candidate{ID:"priority",Utility:.4,Cost:.1,Risk:.05,Urgency:.8,Impact:.4};planned,err:=c.Plan([]Candidate{candidate});if err!=nil{t.Fatal(err)};prioritized,err:=c.Prioritize([]Candidate{candidate});if err!=nil{t.Fatal(err)};if len(planned)!=1||len(prioritized)!=1{t.Fatalf("planned=%v prioritized=%v",planned,prioritized)};if planned[0].Score!=prioritized[0].Score{t.Fatalf("priority score changed unexpectedly: plan=%f prioritize=%f",planned[0].Score,prioritized[0].Score)}}
